INSERT INTO "SyncOutbox"("TableName","RecordKey","Body") VALUES ('Templates',json_array(new."Id"),json_object('AccountId',new."AccountId",'Amount',new."Amount",'CategoryId',new."CategoryId",'CreatedAt',new."CreatedAt",'Icon',new."Icon",'Id',new."Id",'Kind',new."Kind",'Name',new."Name",'Payee',new."Payee",'SortOrder',new."SortOrder",'Title',new."Title",'ToAccountId',new."ToAccountId"));
END;
CREATE TRIGGER "zsync_Templates_update" AFTER UPDATE ON "Templates" WHEN EXISTS(SELECT 1 FROM "SyncBinding" WHERE "Id"=1 AND "Enabled"=1 AND "Applying"=0) AND (old."AccountId" IS NOT new."AccountId" OR old."Amount" IS NOT new."Amount" OR old."CategoryId" IS NOT new."CategoryId" OR old."CreatedAt" IS NOT new."CreatedAt" OR old."Icon" IS NOT new."Icon" OR old."Id" IS NOT new."Id" OR old."Kind" IS NOT new."Kind" OR old."Name" IS NOT new."Name" OR old."Payee" IS NOT new."Payee" OR old."SortOrder" IS NOT new."SortOrder" OR old."Title" IS NOT new."Title" OR old."ToAccountId" IS NOT new."ToAccountId") BEGIN
INSERT INTO "SyncOutbox"("TableName","RecordKey","Body") SELECT 'Templates',json_array(old."Id"),NULL WHERE json_array(old."Id") <> json_array(new."Id");
INSERT INTO "SyncOutbox"("TableName","RecordKey","Body") VALUES ('Templates',json_array(new."Id"),json_object('AccountId',new."AccountId",'Amount',new."Amount",'CategoryId',new."CategoryId",'CreatedAt',new."CreatedAt",'Icon',new."Icon",'Id',new."Id",'Kind',new."Kind",'Name',new."Name",'Payee',new."Payee",'SortOrder',new."SortOrder",'Title',new."Title",'ToAccountId',new."ToAccountId"));
END;
CREATE TRIGGER "zsync_Templates_delete" AFTER DELETE ON "Templates" WHEN EXISTS(SELECT 1 FROM "SyncBinding" WHERE "Id"=1 AND "Enabled"=1 AND "Applying"=0) BEGIN
INSERT INTO "SyncOutbox"("TableName","RecordKey","Body") VALUES ('Templates',json_array(old."Id"),NULL);
END;
